 68	export function useFeldPruefung(schema) {
 69	  const [fehler, setFehler] = useState({});
 70	  const [beruehrt, setBeruehrt] = useState({});
 71	
 72	  const eins = useCallback((feld, werte) => {
 73	    for (const r of schema[feld] || []) {
 74	      const m = r(werte?.[feld], werte);
 75	      if (m) return m;
 76	    }
 77	    return "";
 78	  }, [schema]);
 79	
 80	  const pruefe = useCallback((feld, werte) => {
 81	    const m = eins(feld, werte);
 82	    setFehler((f) => (f[feld] === m ? f : { ...f, [feld]: m }));
 83	    return !m;
 84	  }, [eins]);
 85	
 86	  const alles = useCallback((werte) => {
 87	    const neu = {};
 88	    for (const feld of Object.keys(schema)) neu[feld] = eins(feld, werte);
 89	    setFehler(neu);
 90	    setBeruehrt(Object.fromEntries(Object.keys(schema).map((k) => [k, true])));
 91	    const erster = Object.keys(neu).find((k) => neu[k]);
 92	    if (erster && typeof document !== "undefined") {
 93	      requestAnimationFrame(() => document.querySelector(`[data-feld="${erster}"]`)?.focus());
 94	    }
 95	    return !erster;
 96	  }, [schema, eins]);
 97	
 98	  /** Nach der ersten Berührung live nachprüfen, damit Meldungen beim Korrigieren verschwinden */
 99	  const aendern = useCallback((feld, werte) => {
100	    if (beruehrt[feld]) pruefe(feld, werte);
101	  }, [beruehrt, pruefe]);
102	
103	  const feldProps = (feld, id, werte) => ({
104	    "data-feld": feld,
105	    "aria-invalid": fehler[feld] ? true : undefined,
106	    "aria-describedby": fehler[feld] ? `${id}-fehler` : undefined,
107	    onBlur: () => {
108	      setBeruehrt((b) => ({ ...b, [feld]: true }));
109	      pruefe(feld, werte);
110	    },
111	  });
112	
113	  return { fehler, beruehrt, pruefe, alles, aendern, feldProps };
114	}
