614	function Tacho({ score, farbe }) {
615	  // Halbkreis 180°, Radius 80. Füllung über stroke-dashoffset (pathLength 100) statt stroke-dasharray –
616	  // nur der Versatz wird animiert (DESIGN § 3.3); unter reduced-motion springt der Wert.
617	  // Ergebnis-Moment: Beim Erscheinen füllt sich der Bogen von 0 und die Zahl zählt mit (rAF, ändert nur den Textknoten).
618	  // Das Server-/Erst-Render enthält bereits den Endwert; ohne JS-Effekt oder bei reduzierter Bewegung bleibt er stehen.
619	  const anteil = Math.max(0, Math.min(100, score));
620	  // Nur den Wert des vorhandenen Textknotens ändern (React behält seinen Knoten)
621	  const zahl = (v) => {
622	    const k = zahlRef.current?.firstChild;
623	    if (k) k.nodeValue = String(v);
624	  };
625	  const zahlRef = useRef(null);
626	  const animiert = useRef(false);
627	  // Start bei 0 (Bogen leer), der Effekt füllt ihn – unter reduzierter Bewegung ohne Übergang (motion-safe)
628	  const [gezeigt, setGezeigt] = useState(0);
629	
630	  useLayoutEffect(() => {
631	    if (animiert.current || window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
632	      setGezeigt(anteil);
633	      zahl(score);
634	      return;
635	    }
636	    zahl(0);
637	    let raf = 0;
638	    let start = 0;
639	    const dauer = 900;
640	    const t0 = window.setTimeout(() => {
641	      animiert.current = true;
642	      setGezeigt(anteil);
643	      const schritt = (t) => {
644	        if (!start) start = t;
645	        const p = Math.min(1, (t - start) / dauer);
646	        zahl(Math.round(score * (1 - Math.pow(1 - p, 3))));
647	        if (p < 1) raf = requestAnimationFrame(schritt);
648	      };
649	      raf = requestAnimationFrame(schritt);
650	    }, 160);
651	    return () => {
652	      window.clearTimeout(t0);
653	      cancelAnimationFrame(raf);
654	      zahl(score);
655	    };
656	    // eslint-disable-next-line react-hooks/exhaustive-deps
657	  }, [score]);
658	
659	  return (
660	    <svg viewBox="0 0 200 116" className="h-auto w-full max-w-[220px]" role="img" aria-label={`Punktwert ${score} von 100`}>
661	      <path d="M20 100 A80 80 0 0 1 180 100" fill="none" stroke="rgba(255,255,255,0.12)" strokeWidth="16" strokeLinecap="round" />
662	      <path
663	        d="M20 100 A80 80 0 0 1 180 100"
664	        fill="none"
665	        stroke={farbe}
666	        strokeWidth="16"
667	        strokeLinecap="round"
668	        pathLength={100}
669	        strokeDasharray="100 100"
670	        strokeDashoffset={100 - gezeigt}
671	        className="motion-safe:transition-[stroke-dashoffset] motion-safe:duration-[900ms] motion-safe:ease-ov-out"
672	      />
673	      <text ref={zahlRef} x="100" y="92" textAnchor="middle" className="fill-white font-display text-[40px] font-extrabold" style={{ fontVariantNumeric: "tabular-nums" }}>{score}</text>
674	      <text x="100" y="112" textAnchor="middle" className="fill-white/75 text-[11px]">von 100 Punkten</text>
675	    </svg>
676	  );
677	}
