50	  Object.freeze({
51	    id: "werbeanruf",
52	    version: HINWEIS_VERSION,
53	    nurMitTelefon: true,
54	    aktiv: true,
55	    text: "Ja, ÖkoInvest darf mich auch später telefonisch zu passenden eigenen Angeboten ansprechen. Ich kann das jederzeit widerrufen.",
56	  }),
57	  Object.freeze({
58	    id: "newsletter",
59	    version: HINWEIS_VERSION,
60	    nurMitTelefon: false,
61	    aktiv: true,
62	    // TODO Strang R + Betrieb: Double-Opt-in-Strecke fehlt noch – bis dahin wird nur der Wunsch gespeichert (doi: "ausstehend"), es geht nichts raus.
63	    text: "Ja, ich möchte Fachinformationen und Fristen-Hinweise für mein Land per E-Mail erhalten. Die Anmeldung bestätige ich per E-Mail; Abmeldung jederzeit.",
64	  }),
65	  Object.freeze({
66	    id: "partner",
67	    version: HINWEIS_VERSION,
68	    nurMitTelefon: false,
69	    aktiv: false, // TODO Strang R: Partner namentlich benennen, erst dann einschalten
70	    text: "Ja, meine Anfrage darf an folgende Partner weitergegeben werden: [Partnerliste folgt – Strang R].",
71	  }),
72	]);
73	
74	export const EINWILLIGUNG_IDS = Object.freeze(EINWILLIGUNGEN.filter((e) => e.aktiv).map((e) => e.id));
75	
76	/** Für das Formular: welche Häkchen werden angezeigt? */
77	export function einwilligungenFuer({ mitTelefon }) {
78	  return EINWILLIGUNGEN.filter((e) => e.aktiv && (!e.nurMitTelefon || mitTelefon));
79	}
80	
81	/**
82	 * Eingabe des Formulars → Protokoll-Einträge (nur erteilte, nur bekannte, nur aktive).
83	 * hash: Funktion text → Hex-Hash (Server: SHA-256); am: Zeitstempel (ISO).
84	 * Telefon-Einwilligung ohne Telefonnummer wird verworfen.
85	 */
86	export function einwilligungenAufbereiten(eingabe, { hash, am, telefon }) {
87	  const roh = eingabe && typeof eingabe === "object" && !Array.isArray(eingabe) ? eingabe : {};
88	  const out = [];
89	  for (const e of EINWILLIGUNGEN) {
90	    if (!e.aktiv || roh[e.id] !== true) continue;
91	    if (e.nurMitTelefon && !telefon) continue;
92	    out.push({ id: e.id, erteilt: true, am, version: e.version, textHash: hash(e.text), ...(e.id === "newsletter" ? { doi: "ausstehend" } : {}) });
93	  }
94	  return out;
95	}
