// Schnellprüfung vieler Seiten nacheinander in einem Browser:
// HTTP-Status, Konsolenfehler, horizontaler Überlauf, Bild des oberen Bildschirms.
// Aufruf: node check.mjs <basis-url> <ausgabeordner> <breiten> <pfad1> <pfad2> ...
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";

const [basis, out, breitenArg, ...pfade] = process.argv.slice(2);
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
const ctx = await browser.newContext();
// Cookie-Banner vorab wegklicken, indem wir es einmal schließen
let bannerZu = false;

for (const w of breitenArg.split(",").map(Number)) {
  const page = await ctx.newPage();
  await page.setViewportSize({ width: w, height: w < 700 ? 844 : 900 });
  for (const pfad of pfade) {
    const fehler = [];
    const onC = (m) => m.type() === "error" && fehler.push(m.text());
    const onE = (e) => fehler.push(String(e));
    page.on("console", onC);
    page.on("pageerror", onE);
    let status = 0;
    try {
      const r = await page.goto(basis + pfad, { waitUntil: "load", timeout: 180000 });
      status = r ? r.status() : 0;
      await page.waitForTimeout(1500);
      if (!bannerZu) {
        await page.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 4000 }).then(() => { bannerZu = true; }).catch(() => {});
      }
      const breite = await page.evaluate(() => document.documentElement.scrollWidth);
      const overlay = await page.locator("nextjs-portal").count();
      const name = pfad.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "start";
      await page.screenshot({ path: `${out}/w${w}-${name}.png` });
      const ok = status === 200 && breite <= w && fehler.length === 0;
      console.log(`${ok ? "OK  " : "!!  "} w${w} ${pfad}  status=${status} breite=${breite}${breite > w ? " ÜBERLAUF" : ""} fehler=${fehler.length}${overlay ? " (Dev-Overlay)" : ""}`);
      fehler.slice(0, 3).forEach((f) => console.log("       ! " + f.slice(0, 180)));
    } catch (e) {
      console.log(`!!   w${w} ${pfad}  LADEFEHLER ${String(e).slice(0, 120)}`);
    }

    const r = await fetch(basis + "/icon.svg", { signal: AbortSignal.timeout(ms), redirect: "manual" });
    return r.status > 0 && r.status < 500;
  } catch {
    return false;
  }
}

export async function neuerKontext(browser, { breite = 1440, consent = true } = {}) {
  const ctx = await browser.newContext({ viewport: { width: breite, height: breite < 700 ? 844 : 900 }, reducedMotion: "reduce", locale: "de-DE" });
  if (consent) {
    await ctx.addCookies([{ name: "cookieConsent", value: encodeURIComponent(JSON.stringify(CONSENT_NOTWENDIG)), url: BASIS }]);
  }
  // Externe Dienste nie aufrufen (Analytics, Karten-Kacheln …) – Prüfungen bleiben lokal und datensparsam
  await ctx.route(/^https?:\/\/(?!localhost|127\.0\.0\.1)/, (r) => r.abort());
  return ctx;
}

/** Seite laden; ein noch sichtbares Cookie-Banner (z. B. nach Formatwechsel) mit „Nur notwendige“ schließen. */
export async function lade(page, pfad, { warten = 1200, versuche = 3 } = {}) {
  let r = null;
  for (let v = 1; ; v++) {
    try {
      // erst DOM, dann höchstens 45 s auf „load“ (hängende Nebenressourcen im Dev-Modus sollen nicht blockieren)
      r = await page.goto(BASIS + pfad, { waitUntil: "domcontentloaded", timeout: 180000 });
      await page.waitForLoadState("load", { timeout: 45000 }).catch(() => {});
      break;
    } catch (e) {
      // Dev-Server startet neu (Wächter) → warten und erneut versuchen; andere Fehler sofort melden
      if (v >= versuche || !/ERR_CONNECTION_(REFUSED|RESET)|ERR_EMPTY_RESPONSE|ERR_ABORTED/.test(String(e))) throw e;
      const t0 = Date.now();
      while (Date.now() - t0 < 120000 && !(await serverErreichbar(BASIS, 5000))) await new Promise((ok) => setTimeout(ok, 3000));
    }
  }
